SINA_SMART["infect-antivirals"] = {"lecture":"infect-antivirals","title":"Antiviral drugs for systemic use","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"infect-antivirals:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"infect-antivirals:e0","text":"Acyclovir: HSV ≫ VZV; phosphorylated by viral thymidine kinase.","topic":"Anti-herpesviruses","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e1","text":"Valaciclovir gives 3× acyclovir levels; very active on VZV.","topic":"Anti-herpesviruses","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e2","text":"Famciclovir = prodrug of penciclovir.","topic":"Anti-herpesviruses","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e3","text":"Ganciclovir/valganciclovir: CMV; myelotoxic; not if neutrophils < 500.","topic":"Anti-CMV","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e4","text":"Foscarnet: nephrotoxic, hypercalcaemia, hypokalaemia, genital ulcers.","topic":"Anti-CMV","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e5","text":"Cidofovir: t½ 65 h, spaced dosing, with probenecid; nephrotoxic, uveitis.","topic":"Anti-CMV","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e6","text":"HBV first line: tenofovir.","topic":"Hepatitis B and C","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e7","text":"HCV: -previr (protease), -asvir (NS5A), -buvir (polymerase); sofosbuvir.","topic":"Hepatitis B and C","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e10","text":"Oseltamivir within 48 h; amantadine obsolete (resistance).","topic":"HIV and influenza","sec":4,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e8","text":"NRTI: chain termination; NNRTI: allosteric, low genetic barrier.","topic":"HIV and influenza","sec":4,"importance":"core","highYield":"untested"},{"id":"infect-antivirals:e9","text":"ARV classes: NRTI, NNRTI, PI, integrase inhibitors (+ entry inhibitors).","topic":"HIV and influenza","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1edj68k":"a","1ymiei4":"a","z6fqn1":"a","ng8549":"a","nc31y5":"a","hmyn42":"a","qmv7py":"a","4c9529":"a","1mdwsce":"a","82xyf9":"a","b9toj5":"a","zs7ywj":"a","zbrx3l":"a","1jvxk9t":"a","1ht3nm6":"a","kbnna2":"a","1iu0dgf":"a","6s7s6o":"a","mromwq":"x"},"mapCounts":{"verified":0,"auto":18,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"infect-antivirals:s0":{"s":0,"u":["Antivirals target specific viral steps, so each virus family has its own drugs: herpesviruses (HSV, VZV, CMV), hepatitis B and C , HIV and influenza .","Knowing the spectrum, route, monitoring and main toxicity of each is the core of this lecture."],"dp":[]},"infect-antivirals:e0":{"s":1,"u":["Acyclovir: HSV ≫ VZV; phosphorylated by viral thymidine kinase.","Nucleoside analogues must be phosphorylated to the triphosphate: acyclovir and penciclovir first by viral thymidine kinase , ganciclovir by the viral UL97 phosphotransferase; cidofovir is already monophosphorylated and foscarnet acts directly on the viral DNA polymerase.","Acyclovir : inhibits viral DNA polymerase; very active on HSV-1 and HSV-2 , less on VZV, almost inactive on EBV and CMV; adapt to renal function; caution in pregnancy."],"dp":[{"h":"Why acyclovir spares healthy cells","t":"Acyclovir is harmless until it is phosphorylated, and the first phosphate is added efficiently only by the thymidine kinase that herpes simplex encodes. Uninfected cells barely activate it, so the drug concentrates as a triphosphate inside infected cells, where it blocks the viral DNA polymerase. Viruses that lose or change their thymidine kinase become resistant, and then foscarnet, which needs no activation, is used. Source: the lecture's anti-herpesviridae mechanism diagram."}]},"infect-antivirals:e1":{"s":1,"u":["Valaciclovir gives 3× acyclovir levels; very active on VZV.","Valaciclovir : better absorbed, 3 times the plasma levels of acyclovir, very active on VZV .","Famciclovir : prodrug of penciclovir, active on HSV and VZV."],"dp":[]},"infect-antivirals:e2":{"s":1,"u":["Famciclovir = prodrug of penciclovir.","Famciclovir : prodrug of penciclovir, active on HSV and VZV."],"dp":[]},"infect-antivirals:e3":{"s":2,"u":["Ganciclovir/valganciclovir: CMV; myelotoxic; not if neutrophils < 500.","Slow IV with hydration; adapt to renal function; myelotoxic (neutropenia, thrombocytopenia, anaemia), GI and skin effects, neuropsychological disorders; contraindicated if neutrophils under 500/mm³ .","Valganciclovir (Rovalcyte): oral ganciclovir, better tolerated."],"dp":[]},"infect-antivirals:e4":{"s":2,"u":["Foscarnet: nephrotoxic, hypercalcaemia, hypokalaemia, genital ulcers.","Foscarnet (Foscavir; CMV, HSV, VZV, EBV): 90 mg/kg/12 h IV for 14-21 days with hydration; IV only; avoid other nephrotoxins; renal failure , hypercalcaemia, hypokalaemia, genital ulcers."],"dp":[]},"infect-antivirals:e5":{"s":2,"u":["Cidofovir: t½ 65 h, spaced dosing, with probenecid; nephrotoxic, uveitis.","Cidofovir (Vistide): half-life 65 h, spaced dosing (D1, D7, then every 14 days), broad spectrum; used when ganciclovir and foscarnet are contraindicated; given with hydration and probenecid ; renal failure, uveitis."],"dp":[]},"infect-antivirals:e6":{"s":3,"u":["HBV first line: tenofovir.","High viral load chronic HBV → tenofovir first line .","HBV oral antivirals : tenofovir disoproxil (first line: excellent resistance profile, few renal effects, 1 pill/day, cheaper), tenofovir alafenamide (better tolerated, more expensive), entecavir (good resistance profile), second line telbivudine (neuropathy, myalgia) and adefovir (renal), lamivudine (less potent, resistance within 1-2 years)."],"dp":[]},"infect-antivirals:e7":{"s":3,"u":["HCV: -previr (protease), -asvir (NS5A), -buvir (polymerase); sofosbuvir.","HCV direct-acting antivirals , named by suffix: protease inhibitors -previr (grazoprevir, glecaprevir), NS5A inhibitors -asvir (daclatasvir, velpatasvir, ledipasvir), polymerase inhibitors -buvir (nucleoside: sofosbuvir ; non-nucleoside: dasabuvir).","In Morocco: sofosbuvir with daclatasvir or velpatasvir ."],"dp":[]},"infect-antivirals:e10":{"s":4,"u":["Oseltamivir within 48 h; amantadine obsolete (resistance).","Influenza (Orthomyxoviridae, RNA; types A, B, C; haemagglutinin for attachment, neuraminidase for release): neuraminidase inhibitors oseltamivir (oral, most used; reduces severity if started within 48 hours ), zanamivir (inhaled), peramivir (IV); baloxavir marboxil blocks RNA transcription; amantadine and rimantadine (M2 channel, influenza A only) are no longer recommended because of resistance."],"dp":[]},"infect-antivirals:e8":{"s":4,"u":["NRTI: chain termination; NNRTI: allosteric, low genetic barrier.","NNRTIs (nevirapine, efavirenz, etravirine, rilpivirine, doravirine): bind an allosteric site, non-competitive, low genetic barrier (one mutation can suffice).","Antiretroviral classes : NRTIs (zidovudine, lamivudine, abacavir, tenofovir, emtricitabine): nucleoside analogues at the catalytic site, incorporated into viral DNA → chain termination (no 3'-OH), competitive, rather high genetic barrier."],"dp":[{"h":"Why HIV is treated with several drug classes","t":"HIV's reverse transcriptase makes many errors, so resistant variants arise constantly. A single drug, especially an NNRTI with a low genetic barrier, is quickly defeated by one mutation. Combining drugs from different classes means a virus would need several independent mutations at once, which keeps it suppressed. Source: the lecture's antiretroviral classes slides."}]},"infect-antivirals:e9":{"s":4,"u":["ARV classes: NRTI, NNRTI, PI, integrase inhibitors (+ entry inhibitors).","Entry inhibitors (enfuvirtide, maraviroc).","Integrase inhibitors (dolutegravir, raltegravir, bictegravir, cabotegravir, elvitegravir/cobicistat)."],"dp":[]}},"meta":{"1edj68k":{"a":"recall","vg":"infect-antivirals:e1/recall/1"},"1ymiei4":{"a":"recall","vg":"infect-antivirals:e0/recall/1"},"z6fqn1":{"a":"recall","vg":"infect-antivirals:e1/recall/2"},"ng8549":{"a":"recall","vg":"infect-antivirals:e2/recall/1"},"nc31y5":{"a":"recall","vg":"infect-antivirals:e3/recall/1"},"hmyn42":{"a":"recall","vg":"infect-antivirals:e3/recall/2"},"qmv7py":{"a":"recall","vg":"infect-antivirals:e4/recall/1"},"4c9529":{"a":"recall","vg":"infect-antivirals:e5/recall/1"},"1mdwsce":{"a":"recall","vg":"infect-antivirals:e6/recall/1"},"82xyf9":{"a":"recall","vg":"infect-antivirals:e6/recall/2"},"b9toj5":{"a":"recall","vg":"infect-antivirals:e7/recall/1"},"zs7ywj":{"a":"recall","vg":"infect-antivirals:e7/recall/2"},"zbrx3l":{"a":"recall","vg":"infect-antivirals:e8/recall/1"},"1jvxk9t":{"a":"recall","vg":"infect-antivirals:e8/recall/2"},"1ht3nm6":{"a":"recall","vg":"infect-antivirals:e9/recall/1"},"kbnna2":{"a":"recall","vg":"infect-antivirals:e9/recall/1"},"1iu0dgf":{"a":"application","vg":"infect-antivirals:e10/application/1"},"6s7s6o":{"a":"relationship","vg":"infect-antivirals:e10/relationship/1"}},"explRev":"3d9d99af6d70"};
